/**
 * Fixtures for the server suite: a throwaway SQLite file plus a helper that
 * builds one fully-populated tenant (org, four members, a project) through the
 * real repositories, so the rows under test are the rows production writes.
 *
 * Kept apart from `tests/helpers/*` — those belong to another owner.
 */
import { mkdtempSync, rmSync } from "node:fs";
import { tmpdir } from "node:os";
import { join } from "node:path";
import { runMigrations } from "@/server/db/migrate";
import * as memberRepo from "@/server/repositories/member-repository";
import * as orgRepo from "@/server/repositories/organization-repository";
import * as projectRepo from "@/server/repositories/project-repository";
import * as subscriptionRepo from "@/server/repositories/subscription-repository";
import * as userRepo from "@/server/repositories/user-repository";
import type { PlanId } from "@/types/billing";
import type { OrgId, UserId } from "@/types/common";
import type { Actor, Role } from "@/types/member";
import type { Organization } from "@/types/organization";
import type { Project } from "@/types/project";

export interface Tenant {
  readonly org: Organization;
  readonly project: Project;
  readonly actors: Readonly<Record<Role, Actor>>;
  readonly userIds: Readonly<Record<Role, UserId>>;
}

const ROLES: readonly Role[] = ["owner", "admin", "member", "viewer"];

/**
 * Points the connection at a fresh database file and migrates it. Call from
 * `beforeAll`; the returned function removes the directory again.
 *
 * A file rather than `:memory:` because `runMigrations` and the app client
 * open separate connections, and only a file is shared between the two.
 */
export async function useTemporaryDatabase(): Promise<() => void> {
  const dir = mkdtempSync(join(tmpdir(), "taskflow-test-"));
  const path = join(dir, "taskflow.db");

  process.env.TASKFLOW_DB_PATH = path;
  await runMigrations(path);

  return () => {
    rmSync(dir, { recursive: true, force: true });
  };
}

/**
 * Creates one organization with a member in every role and a single project.
 * `plan` decides which quotas apply — the free plan's three seats is what the
 * invite-limit test leans on.
 */
export async function createTenant(
  slug: string,
  plan: PlanId = "growth",
): Promise<Tenant> {
  const owner = await userRepo.insertUser({
    email: `owner@${slug}.test`,
    name: `${slug} owner`,
    passwordHash: "seed",
  });

  const org = await orgRepo.insertOrg(
    { name: `${slug} inc`, slug, plan },
    owner.id,
  );

  await subscriptionRepo.insertSubscription(org.id, plan, "monthly");

  const userIds: Partial<Record<Role, UserId>> = {};
  const actors: Partial<Record<Role, Actor>> = {};

  for (const role of ROLES) {
    const user =
      role === "owner"
        ? owner
        : await userRepo.insertUser({
            email: `${role}@${slug}.test`,
            name: `${slug} ${role}`,
            passwordHash: "seed",
          });

    await memberRepo.insertMember(org.id, user.id, role, null);

    userIds[role] = user.id;
    actors[role] = { userId: user.id, orgId: org.id, role };
  }

  const project = await projectRepo.insertProject({
    orgId: org.id,
    name: `${slug} platform`,
    slug: "platform",
    key: "PLAT",
    description: null,
    visibility: "org",
    leadId: owner.id,
    color: "#6366f1",
    targetDate: null,
  });

  return {
    org,
    project,
    actors: actors as Readonly<Record<Role, Actor>>,
    userIds: userIds as Readonly<Record<Role, UserId>>,
  };
}

/** Minimal `CreateIssueInput` with the schema's defaults already applied. */
export function issueInput(
  orgId: OrgId,
  projectId: Project["id"],
  overrides: Partial<{
    title: string;
    assigneeId: UserId | null;
    dueAt: string | null;
  }> = {},
) {
  return {
    orgId,
    projectId,
    title: overrides.title ?? "Ship the thing",
    description: null,
    status: "backlog" as const,
    priority: "none" as const,
    assigneeId: (overrides.assigneeId ?? null) as UserId | null,
    parentId: null,
    estimate: null,
    dueAt: (overrides.dueAt ?? null) as never,
    labelIds: [],
  };
}
/**
 * Attachment metadata plus the storage quota guard.
 *
 * Must call (do not reimplement): assertCan, assertOrgScope, wouldExceedLimit
 */
import { wouldExceedLimit } from "@/config/plan-limits";
import { assertCan } from "@/lib/permissions";
import { assertOrgScope } from "@/lib/tenant";
import * as attachmentRepo from "@/server/repositories/attachment-repository";
import * as issueRepo from "@/server/repositories/issue-repository";
import * as orgRepo from "@/server/repositories/organization-repository";
import * as usageRepo from "@/server/repositories/usage-repository";
import { issueResource, requireFound } from "./_support";
import type {
  CreateAttachmentInput,
  DeleteAttachmentInput,
} from "@/schemas/attachment";
import type { IssueId, OrgId } from "@/types/common";
import type { IssueAttachment } from "@/types/issue";
import type { Actor } from "@/types/member";

const BYTES_PER_MB = 1024 * 1024;

export async function listAttachments(
  actor: Actor,
  orgId: OrgId,
  issueId: IssueId,
): Promise<readonly IssueAttachment[]> {
  assertOrgScope(actor, orgId);

  const issue = requireFound(
    await issueRepo.findIssueById(orgId, issueId),
    "Issue",
    issueId,
  );
  assertCan(actor, "issue:read", issueResource(issue));

  return attachmentRepo.listAttachments(orgId, issueId);
}

/**
 * Records an upload after checking the org still has storage left. The quota
 * is in megabytes and the upload is in bytes, so the incoming size is rounded
 * up to whole megabytes before the comparison — half a megabyte still costs
 * one against the plan.
 */
export async function addAttachment(
  actor: Actor,
  input: CreateAttachmentInput,
): Promise<IssueAttachment> {
  assertOrgScope(actor, input.orgId);

  const issue = requireFound(
    await issueRepo.findIssueById(input.orgId, input.issueId),
    "Issue",
    input.issueId,
  );
  assertCan(actor, "issue:update", issueResource(issue));

  const org = requireFound(
    await orgRepo.findOrgById(input.orgId),
    "Organization",
    input.orgId,
  );

  const usage = await usageRepo.getUsage(input.orgId);
  const requestedMb = Math.ceil(input.sizeBytes / BYTES_PER_MB);

  if (
    wouldExceedLimit(org.plan, "storageMb", usage.storageMbUsed, requestedMb)
  ) {
    throw new Error(
      `Plan ${org.plan} has no room for another ${requestedMb} MB`,
    );
  }

  const attachment = await attachmentRepo.insertAttachment(
    input,
    actor.userId,
  );
  await usageRepo.incrementUsage(input.orgId, { storageMbUsed: requestedMb });

  return attachment;
}

/** Removing an attachment gives the megabytes back to the quota. */
export async function removeAttachment(
  actor: Actor,
  input: DeleteAttachmentInput,
): Promise<void> {
  assertOrgScope(actor, input.orgId);

  const attachment = requireFound(
    await findAttachment(input.orgId, input.attachmentId),
    "Attachment",
    input.attachmentId,
  );

  const issue = requireFound(
    await issueRepo.findIssueById(input.orgId, attachment.issueId),
    "Issue",
    attachment.issueId,
  );
  assertCan(actor, "issue:update", issueResource(issue));

  await attachmentRepo.deleteAttachment(input.orgId, input.attachmentId);
  await usageRepo.incrementUsage(input.orgId, {
    storageMbUsed: -Math.ceil(attachment.sizeBytes / BYTES_PER_MB),
  });
}

/**
 * The attachment repository only reads by issue, because that is the only way
 * the UI ever reaches one. A delete arrives with just an id, so the org's
 * issues are walked until the row turns up.
 */
async function findAttachment(
  orgId: OrgId,
  attachmentId: string,
): Promise<IssueAttachment | null> {
  const page = await issueRepo.listIssues({
    orgId,
    limit: 100,
    cursor: null,
    includeArchived: true,
  });

  for (const issue of page.items) {
    const rows = await attachmentRepo.listAttachments(orgId, issue.id);
    const match = rows.find((row) => row.id === attachmentId);
    if (match) return match;
  }

  return null;
}
/**
 * Webhook endpoint management and the bridge from `webhook.delivery_requested` to the delivery queue.
 *
 * Must call (do not reimplement): assertCan, assertOrgScope, subscribe, isEnabled, wouldExceedLimit
 */
import { createHmac } from "node:crypto";
import { wouldExceedLimit } from "@/config/plan-limits";
import { subscribe } from "@/lib/event-bus";
import { isEnabled } from "@/lib/feature-flags";
import { randomToken } from "@/lib/hash";
import { assertCan } from "@/lib/permissions";
import { assertOrgScope } from "@/lib/tenant";
import * as orgRepo from "@/server/repositories/organization-repository";
import * as webhookRepo from "@/server/repositories/webhook-repository";
import { requireFound, webhookResource } from "./_support";
import type {
  CreateWebhookInput,
  DeleteWebhookInput,
  UpdateWebhookInput,
} from "@/schemas/webhook";
import type { WebhookEndpointRow } from "@/server/db/schema/webhooks";
import type { OrgId } from "@/types/common";
import type { Unsubscribe } from "@/types/event";
import type { FlagContext } from "@/types/feature-flag";
import type { Actor } from "@/types/member";

/** Length in bytes of a generated endpoint signing secret. */
const SECRET_BYTES = 32;

export async function listWebhooks(
  actor: Actor,
  orgId: OrgId,
): Promise<readonly WebhookEndpointRow[]> {
  assertOrgScope(actor, orgId);
  assertCan(actor, "webhook:manage", webhookResource(orgId, null));
  return webhookRepo.listEndpoints(orgId);
}

/**
 * Creating an endpoint is gated twice: the `webhooks` flag has to be on for
 * the org's plan, and the plan's endpoint count must have room. A secret is
 * minted here and never regenerated — rotating it means deleting the endpoint.
 */
export async function createWebhook(
  actor: Actor,
  input: CreateWebhookInput,
): Promise<WebhookEndpointRow> {
  assertOrgScope(actor, input.orgId);
  assertCan(actor, "webhook:manage", webhookResource(input.orgId, null));

  const org = requireFound(
    await orgRepo.findOrgById(input.orgId),
    "Organization",
    input.orgId,
  );

  if (!isEnabled("webhooks", flagContextFor(actor, org.plan, org.settings.enabledFlagOverrides))) {
    throw new Error("Outgoing webhooks are not included in this plan");
  }

  const used = await webhookRepo.countEndpoints(input.orgId);
  if (wouldExceedLimit(org.plan, "webhooks", used)) {
    throw new Error(`Plan ${org.plan} allows ${used} webhook endpoints`);
  }

  return webhookRepo.insertEndpoint(input, randomToken(SECRET_BYTES));
}

export async function updateWebhook(
  actor: Actor,
  input: UpdateWebhookInput,
): Promise<WebhookEndpointRow> {
  assertOrgScope(actor, input.orgId);
  assertCan(actor, "webhook:manage", webhookResource(input.orgId, input.webhookId));
  return webhookRepo.updateEndpoint(input);
}

export async function deleteWebhook(
  actor: Actor,
  input: DeleteWebhookInput,
): Promise<void> {
  assertOrgScope(actor, input.orgId);
  assertCan(actor, "webhook:manage", webhookResource(input.orgId, input.webhookId));
  await webhookRepo.deleteEndpoint(input.orgId, input.webhookId);
}

/**
 * HMAC-SHA256 over the raw body, hex encoded. The receiving end recomputes
 * this from the same secret — it is the only thing proving the delivery came
 * from Taskflow, so the payload string must be signed byte-for-byte as sent.
 */
export function signPayload(secret: string, payload: string): string {
  return createHmac("sha256", secret).update(payload, "utf8").digest("hex");
}

/**
 * Fans domain events out into the delivery table. Each org's endpoints
 * declare which event types they want, so an endpoint only ever receives what
 * it subscribed to; the job drains the rows afterwards.
 */
export function registerWebhookListeners(): Unsubscribe {
  const offs: Unsubscribe[] = [
    subscribe("webhook.delivery_requested", async (payload) => {
      await enqueueForOrg(
        payload.orgId,
        payload.eventType,
        JSON.stringify(payload.payload),
      );
    }),
    subscribe("issue.created", async (payload) => {
      await enqueueForOrg(payload.orgId, "issue.created", JSON.stringify(payload));
    }),
    subscribe("issue.status_changed", async (payload) => {
      await enqueueForOrg(
        payload.orgId,
        "issue.status_changed",
        JSON.stringify(payload),
      );
    }),
    subscribe("comment.created", async (payload) => {
      await enqueueForOrg(
        payload.orgId,
        "comment.created",
        JSON.stringify(payload),
      );
    }),
    subscribe("billing.plan_changed", async (payload) => {
      await enqueueForOrg(
        payload.orgId,
        "billing.plan_changed",
        JSON.stringify(payload),
      );
    }),
  ];

  return () => {
    for (const off of offs) off();
  };
}

async function enqueueForOrg(
  orgId: OrgId,
  eventType: string,
  payload: string,
): Promise<void> {
  const endpoints = await webhookRepo.listEndpoints(orgId);

  for (const endpoint of endpoints) {
    if (!endpoint.enabled) continue;

    const wanted: readonly string[] = JSON.parse(endpoint.eventTypes) as string[];
    if (!wanted.includes(eventType)) continue;

    await webhookRepo.enqueueDelivery(orgId, endpoint.id, eventType, payload);
  }
}

function flagContextFor(
  actor: Actor,
  plan: FlagContext["plan"],
  overrides: readonly string[],
): FlagContext {
  return {
    orgId: actor.orgId,
    userId: actor.userId,
    plan,
    role: actor.role,
    overrides,
  };
}
/**
 * Issue creation authorization, quota refusal and emitted events.
 *
 * Owner C implements `@/server/services/issue-service`; the integration pass
 * fills these in once it exists. Fixtures: `tests/helpers/factories.ts`.
 */
import { afterAll, beforeAll, describe, expect, it, vi } from "vitest";

vi.mock("@/lib/id", () => import("../server/_support/doubles/id"));
vi.mock("@/lib/logger", async () => (await import("../server/_support/doubles/misc")).loggerModule);

import { subscribe } from "@/lib/event-bus";
import { PermissionDeniedError } from "@/lib/permissions";
import * as issueRepo from "@/server/repositories/issue-repository";
import * as issueService from "@/server/services/issue-service";
import { createTenant, issueInput, useTemporaryDatabase } from "../server/_support/fixtures";
import type { Tenant } from "../server/_support/fixtures";

let cleanup: () => void;
let tenant: Tenant;

beforeAll(async () => {
  cleanup = await useTemporaryDatabase();
  tenant = await createTenant("issuesvc");
});

afterAll(() => {
  cleanup();
});

describe("services/issue-service", () => {
  it("refuses issue creation to an actor without issue:create", async () => {
    await expect(
      issueService.createIssue(
        tenant.actors.viewer,
        issueInput(tenant.org.id, tenant.project.id, { title: "Viewer can't do this" }),
      ),
    ).rejects.toBeInstanceOf(PermissionDeniedError);
  });

  it("refuses creation when the project is at its plan issue quota", async () => {
    const quotaTenant = await createTenant("issuequota", "free");

    // The free plan allows 100 issues per project; seed that many directly
    // through the repository so the service boundary is the only thing under
    // test here.
    for (let number = 1; number <= 100; number += 1) {
      await issueRepo.insertIssue(
        issueInput(quotaTenant.org.id, quotaTenant.project.id, {
          title: `Seed issue ${number}`,
        }),
        quotaTenant.actors.member.userId,
        number,
      );
    }

    await expect(
      issueService.createIssue(
        quotaTenant.actors.member,
        issueInput(quotaTenant.org.id, quotaTenant.project.id, {
          title: "One too many",
        }),
      ),
    ).rejects.toThrow(/allows no more issues/);
  });

  it("emits issue.created with the persisted issue's fields", async () => {
    const received: unknown[] = [];
    const off = subscribe("issue.created", (payload) => {
      received.push(payload);
    });

    try {
      const issue = await issueService.createIssue(
        tenant.actors.member,
        issueInput(tenant.org.id, tenant.project.id, { title: "Ship the launch" }),
      );

      expect(received).toHaveLength(1);
      expect(received[0]).toMatchObject({
        issueId: issue.id,
        projectId: issue.projectId,
        title: issue.title,
        priority: issue.priority,
      });
    } finally {
      off();
    }
  });

  it("emits issue.status_changed with the previous and new status", async () => {
    const issue = await issueService.createIssue(
      tenant.actors.member,
      issueInput(tenant.org.id, tenant.project.id, { title: "Status change target" }),
    );

    const received: unknown[] = [];
    const off = subscribe("issue.status_changed", (payload) => {
      received.push(payload);
    });

    try {
      await issueService.changeIssueStatus(tenant.actors.member, {
        orgId: tenant.org.id,
        issueId: issue.id,
        status: "in_progress",
      });

      expect(received).toHaveLength(1);
      expect(received[0]).toMatchObject({
        issueId: issue.id,
        from: "backlog",
        to: "in_progress",
      });
    } finally {
      off();
    }
  });

  it("emits issue.assigned with the previous and new assignee", async () => {
    const issue = await issueService.createIssue(
      tenant.actors.member,
      issueInput(tenant.org.id, tenant.project.id, { title: "Assignment target" }),
    );

    const received: unknown[] = [];
    const off = subscribe("issue.assigned", (payload) => {
      received.push(payload);
    });

    try {
      await issueService.assignIssue(tenant.actors.member, {
        orgId: tenant.org.id,
        issueId: issue.id,
        assigneeId: tenant.userIds.member,
      });

      expect(received).toHaveLength(1);
      expect(received[0]).toMatchObject({
        issueId: issue.id,
        previousAssigneeId: null,
        assigneeId: tenant.userIds.member,
      });
    } finally {
      off();
    }
  });

  it("archives rather than deletes, emitting issue.archived", async () => {
    const issue = await issueService.createIssue(
      tenant.actors.member,
      issueInput(tenant.org.id, tenant.project.id, { title: "Archive target" }),
    );

    const received: unknown[] = [];
    const off = subscribe("issue.archived", (payload) => {
      received.push(payload);
    });

    try {
      const archived = await issueService.archiveIssue(
        tenant.actors.member,
        tenant.org.id,
        issue.id,
      );

      expect(archived.archivedAt).not.toBeNull();

      // Still reachable by id: archiving patches the row rather than deleting it.
      const stillThere = await issueRepo.findIssueById(tenant.org.id, issue.id);
      expect(stillThere).not.toBeNull();
      expect(stillThere?.archivedAt).not.toBeNull();

      expect(received).toHaveLength(1);
      expect(received[0]).toMatchObject({ issueId: issue.id, projectId: issue.projectId });
    } finally {
      off();
    }
  });
});
